package com.procurement.rfq.controller;import com.procurement.common.response.*;import com.procurement.rfq.dto.response.*;import com.procurement.rfq.service.*;import org.springframework.data.domain.*;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/rfq-lines")public class RfqLineController{private final RfqLineService service;public RfqLineController(RfqLineService s){service=s;}@GetMapping public ApiResponse<PageResponse<RfqLineResponse>>search(@RequestParam(required=false)Long rfqId,@RequestParam(required=false)Long productId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(defaultValue="id")String sort,@RequestParam(defaultValue="asc")String direction){return ApiResponse.success(service.search(rfqId,productId,PageRequest.of(page,size,Sort.by(Sort.Direction.fromString(direction),sort))));}@GetMapping("/{id}")public ApiResponse<RfqLineResponse>get(@PathVariable Long id){return ApiResponse.success(service.get(id));}}
